void no_funciona(int x) {
    x = 100;  // solo cambia la copia local
}

void si_funciona(int *x) {
    *x = 100;  // cambia el valor real, siguiendo el puntero
}

int main() {
    int numero = 5;

    no_funciona(numero);
    printf("Despues de no_funciona: %d\n", numero);

    si_funciona(&numero);
    printf("Despues de si_funciona: %d\n", numero);
    return 0;
}

