struct Nodo {
    int valor;
    struct Nodo *siguiente;
};

struct Nodo* insertar_al_inicio(struct Nodo *cabeza, int valor) {
    struct Nodo *nuevo = malloc(sizeof(struct Nodo));
    nuevo->valor = valor;
    nuevo->siguiente = cabeza;
    return nuevo;
}

int sumar_lista(struct Nodo *cabeza) {
    int suma = 0;
    while (cabeza != NULL) {
        suma += cabeza->valor;
        cabeza = cabeza->siguiente;
    }
    return suma;
}
